import sqlite3
import pandas as pd

def task_func(db_name, table_name):
    def quote_identifier(identifier):
        return '"' + str(identifier).replace('"', '""') + '"'

    conn = sqlite3.connect(db_name)
    try:
        df = pd.read_sql_query(f"SELECT * FROM {quote_identifier(table_name)}", conn)
    finally:
        conn.close()

    if "id" in df.columns:
        df = df.drop(columns=["id"])

    numeric_df = df.select_dtypes(include="number")

    if numeric_df.shape[1] < 2:
        raise ValueError("The table has less than two numerical columns.")

    x_col = numeric_df.columns[0]
    y_col = numeric_df.columns[1]

    ax = numeric_df.plot.scatter(x=x_col, y=y_col)
    ax.set_xlabel(x_col)
    ax.set_ylabel(y_col)
    return ax
